static int send_all(SOCKET s,const char*b,int n){int p=0;while(p<n){int k=send(s,b+p,n-p,0);if(k<=0)return 0;p+=k;}return 1;}
static const char*mime(const char*p){const char*e=strrchr(p,'.');if(!e)return"application/octet-stream";if(!_stricmp(e,".html"))return"text/html; charset=utf-8";if(!_stricmp(e,".js"))return"application/javascript; charset=utf-8";if(!_stricmp(e,".json"))return"application/json; charset=utf-8";if(!_stricmp(e,".css"))return"text/css; charset=utf-8";if(!_stricmp(e,".png"))return"image/png";if(!_stricmp(e,".jpg")||!_stricmp(e,".jpeg"))return"image/jpeg";if(!_stricmp(e,".webp"))return"image/webp";return"application/octet-stream";}
static void text_response(SOCKET c,int code,const char*reason,const char*body){char h[1024];int z=(int)strlen(body),n=snprintf(h,sizeof(h),"HTTP/1.1 %d %s\r\nContent-Type: text/plain; charset=utf-8\r\nContent-Length: %d\r\nCache-Control: no-store\r\nConnection: close\r\n\r\n",code,reason,z);send_all(c,h,n);send_all(c,body,z);}
static int header_value(const char*headers,const char*name,char*out,size_t cap){size_t nl=strlen(name);const char*p=headers;while((p=strstr(p,"\r\n"))){p+=2;if(!_strnicmp(p,name,nl)&&p[nl]==':'){p+=nl+1;while(*p==' '||*p=='\t')p++;const char*e=strstr(p,"\r\n");if(!e)return 0;size_t n=(size_t)(e-p);if(n>=cap)n=cap-1;memcpy(out,p,n);out[n]=0;return 1;}}return 0;}
static wchar_t*widen(const char*s){int n=MultiByteToWideChar(CP_UTF8,0,s,-1,NULL,0);wchar_t*w=(wchar_t*)calloc(n,sizeof(wchar_t));if(w)MultiByteToWideChar(CP_UTF8,0,s,-1,w,n);return w;}

static int safe_component(const char*s){if(!s||!*s||!strcmp(s,".")||!strcmp(s,".."))return 0;for(const char*p=s;*p;p++)if(!((*p>='a'&&*p<='z')||(*p>='A'&&*p<='Z')||(*p>='0'&&*p<='9')||*p=='-'||*p=='_'))return 0;return 1;}
static void output_root(const char*root,char*out,size_t cap){snprintf(out,cap,"%s\\output",root);CreateDirectoryA(out,NULL);}
static int write_file(const char*path,const void*data,size_t len){FILE*f=fopen(path,"wb");if(!f)return 0;size_t n=fwrite(data,1,len,f);fclose(f);return n==len;}
static int read_file_response(SOCKET c,const char*method,const char*path){FILE*f=fopen(path,"rb");if(!f){text_response(c,404,"Not Found","Not Found");return 0;}_fseeki64(f,0,SEEK_END);__int64 sz=_ftelli64(f);_fseeki64(f,0,SEEK_SET);char h[1024];int hn=snprintf(h,sizeof(h),"HTTP/1.1 200 OK\r\nContent-Type: %s\r\nContent-Length: %lld\r\nCache-Control: no-store\r\nConnection: close\r\n\r\n",mime(path),(long long)sz);send_all(c,h,hn);if(_stricmp(method,"HEAD")){char b[CHUNK];int k;while((k=(int)fread(b,1,sizeof(b),f))>0)if(!send_all(c,b,k))break;}fclose(f);return 1;}
static int query_value(const char*target,const char*name,char*out,size_t cap){const char*q=strchr(target,'?');if(!q)return 0;q++;size_t nl=strlen(name);while(*q){const char*e=strchr(q,'&');if(!e)e=q+strlen(q);if((size_t)(e-q)>nl&&strncmp(q,name,nl)==0&&q[nl]=='='){size_t n=(size_t)(e-q)-nl-1;if(!n||n>=cap)return 0;memcpy(out,q+nl+1,n);out[n]=0;return 1;}if(!*e)break;q=e+1;}return 0;}
static void history_paths(const char*root,const char*project,char*dir,size_t dcap){char out[MAX_PATH*4];output_root(root,out,sizeof(out));snprintf(dir,dcap,"%s\\%s",out,project);CreateDirectoryA(dir,NULL);}
static void refresh_records_index(const char*dir){char pattern[MAX_PATH*4],indexPath[MAX_PATH*4];snprintf(pattern,sizeof(pattern),"%s\\record-*.json",dir);snprintf(indexPath,sizeof(indexPath),"%s\\records.json",dir);HANDLE h;WIN32_FIND_DATAA fd;h=FindFirstFileA(pattern,&fd);if(h==INVALID_HANDLE_VALUE){write_file(indexPath,"[]",2);return;}size_t cap=65536,len=0;char*all=(char*)malloc(cap);if(!all){FindClose(h);return;}all[len++]='[';int first=1;do{char path[MAX_PATH*4];snprintf(path,sizeof(path),"%s\\%s",dir,fd.cFileName);FILE*f=fopen(path,"rb");if(!f)continue;_fseeki64(f,0,SEEK_END);long long sz=_ftelli64(f);_fseeki64(f,0,SEEK_SET);if(sz<0||sz>2000000){fclose(f);continue;}if(len+(size_t)sz+3>cap){while(len+(size_t)sz+3>cap)cap*=2;char*next=(char*)realloc(all,cap);if(!next){fclose(f);free(all);FindClose(h);return;}all=next;}if(!first)all[len++]=',';first=0;len+=fread(all+len,1,(size_t)sz,f);fclose(f);}while(FindNextFileA(h,&fd));FindClose(h);all[len++]=']';write_file(indexPath,all,len);free(all);}
static void remove_tree(const char*dir){char pattern[MAX_PATH*4];snprintf(pattern,sizeof(pattern),"%s\\*",dir);WIN32_FIND_DATAA fd;HANDLE h=FindFirstFileA(pattern,&fd);if(h!=INVALID_HANDLE_VALUE){do{if(!strcmp(fd.cFileName,".")||!strcmp(fd.cFileName,".."))continue;char path[MAX_PATH*4];snprintf(path,sizeof(path),"%s\\%s",dir,fd.cFileName);if(fd.dwFileAttributes&FILE_ATTRIBUTE_DIRECTORY)remove_tree(path);else DeleteFileA(path);}while(FindNextFileA(h,&fd));FindClose(h);}RemoveDirectoryA(dir);}

static void history_record(SOCKET c,const char*root,const char*headers,unsigned char*body,DWORD total){char project[256],record[256],mlbuf[64];if(!header_value(headers,"X-History-Project",project,sizeof(project))||!header_value(headers,"X-History-Record",record,sizeof(record))||!header_value(headers,"X-History-Meta-Length",mlbuf,sizeof(mlbuf))||!safe_component(project)||!safe_component(record)){text_response(c,400,"Bad Request","Invalid history record headers");return;}DWORD metaLen=(DWORD)strtoul(mlbuf,NULL,10);if(!metaLen||metaLen>=total){text_response(c,400,"Bad Request","Invalid history metadata");return;}char dir[MAX_PATH*4],path[MAX_PATH*4];EnterCriticalSection(&history_lock);history_paths(root,project,dir,sizeof(dir));snprintf(path,sizeof(path),"%s\\record-%s.json",dir,record);if(!write_file(path,body,metaLen)){LeaveCriticalSection(&history_lock);text_response(c,500,"Error","Unable to save history metadata");return;}snprintf(path,sizeof(path),"%s\\image-%s.png",dir,record);if(!write_file(path,body+metaLen,total-metaLen)){LeaveCriticalSection(&history_lock);text_response(c,500,"Error","Unable to save history image");return;}refresh_records_index(dir);LeaveCriticalSection(&history_lock);text_response(c,200,"OK","{\"ok\":true}");}
static void history_projects(SOCKET c,const char*root,const char*method,unsigned char*body,DWORD total){char out[MAX_PATH*4],path[MAX_PATH*4];output_root(root,out,sizeof(out));snprintf(path,sizeof(path),"%s\\projects.json",out);if(!_stricmp(method,"POST")){EnterCriticalSection(&history_lock);int ok=total&&write_file(path,body,total);LeaveCriticalSection(&history_lock);if(!ok){text_response(c,500,"Error","Unable to save project index");return;}text_response(c,200,"OK","{\"ok\":true}");return;}if(!_stricmp(method,"GET")||!_stricmp(method,"HEAD")){FILE*f=fopen(path,"rb");if(!f){const char*empty="{\"version\":1,\"projects\":[]}";write_file(path,empty,strlen(empty));}else fclose(f);read_file_response(c,method,path);return;}text_response(c,405,"Method Not Allowed","Method Not Allowed");}
static void history_delete_project(SOCKET c,const char*root,const char*headers){char project[256];if(!header_value(headers,"X-History-Project",project,sizeof(project))||!safe_component(project)){text_response(c,400,"Bad Request","Invalid history project");return;}char dir[MAX_PATH*4];EnterCriticalSection(&history_lock);history_paths(root,project,dir,sizeof(dir));remove_tree(dir);LeaveCriticalSection(&history_lock);text_response(c,200,"OK","{\"ok\":true}");}
static void history_delete_record(SOCKET c,const char*root,const char*headers){char project[256],record[256];if(!header_value(headers,"X-History-Project",project,sizeof(project))||!header_value(headers,"X-History-Record",record,sizeof(record))||!safe_component(project)||!safe_component(record)){text_response(c,400,"Bad Request","Invalid history record");return;}char dir[MAX_PATH*4],path[MAX_PATH*4];EnterCriticalSection(&history_lock);history_paths(root,project,dir,sizeof(dir));snprintf(path,sizeof(path),"%s\\record-%s.json",dir,record);DeleteFileA(path);snprintf(path,sizeof(path),"%s\\image-%s.png",dir,record);DeleteFileA(path);refresh_records_index(dir);LeaveCriticalSection(&history_lock);text_response(c,200,"OK","{\"ok\":true}");}
static int history_request(SOCKET c,const char*root,const char*method,char*target,const char*headers,unsigned char*body,DWORD total){char path[4096];strncpy(path,target,sizeof(path)-1);path[sizeof(path)-1]=0;char*q=strchr(path,'?');if(q)*q=0;if(!strncmp(path,"/history/projects",17)&&!path[17]){history_projects(c,root,method,body,total);return 1;}if(!strcmp(path,"/history/record")&&!_stricmp(method,"POST")){history_record(c,root,headers,body,total);return 1;}if(!strcmp(path,"/history/record/delete")&&!_stricmp(method,"POST")){history_delete_record(c,root,headers);return 1;}if(!strcmp(path,"/history/project/delete")&&!_stricmp(method,"POST")){history_delete_project(c,root,headers);return 1;}if((!strcmp(path,"/history/records")||!strcmp(path,"/history/image"))&&!_stricmp(method,"GET")){char project[256],record[256],dir[MAX_PATH*4],file[MAX_PATH*4];if(!query_value(target,"project",project,sizeof(project))||!safe_component(project)){text_response(c,400,"Bad Request","Invalid history project");return 1;}history_paths(root,project,dir,sizeof(dir));if(!strcmp(path,"/history/records")){snprintf(file,sizeof(file),"%s\\records.json",dir);FILE*f=fopen(file,"rb");if(f){fclose(f);read_file_response(c,method,file);}else text_response(c,200,"OK","[]");}else{if(!query_value(target,"record",record,sizeof(record))||!safe_component(record)){text_response(c,400,"Bad Request","Invalid history record");return 1;}snprintf(file,sizeof(file),"%s\\image-%s.png",dir,record);read_file_response(c,method,file);}return 1;}if(!strcmp(path,"/history/info")&&(!_stricmp(method,"GET")||!_stricmp(method,"HEAD"))){text_response(c,200,"OK","{\"mode\":\"default\",\"folder\":\"output\"}");return 1;}return 0;}

