int main(void){SetConsoleOutputCP(CP_UTF8);char root[MAX_PATH*4];DWORD n=GetModuleFileNameA(NULL,root,sizeof(root));if(!n||n>=sizeof(root))return 1;char*s=strrchr(root,'\\');if(s)*s=0;WSADATA w;if(WSAStartup(MAKEWORD(2,2),&w))return 1;InitializeCriticalSection(&history_lock);SOCKET server=INVALID_SOCKET;int port;for(port=8765;port<=8785;port++){server=socket(AF_INET,SOCK_STREAM,IPPROTO_TCP);struct sockaddr_in a;memset(&a,0,sizeof(a));a.sin_family=AF_INET;a.sin_addr.s_addr=htonl(INADDR_LOOPBACK);a.sin_port=htons((u_short)port);if(server!=INVALID_SOCKET&&bind(server,(struct sockaddr*)&a,sizeof(a))==0&&listen(server,SOMAXCONN)==0)break;if(server!=INVALID_SOCKET)closesocket(server);server=INVALID_SOCKET;}if(server==INVALID_SOCKET){DeleteCriticalSection(&history_lock);MessageBoxA(NULL,"Ports 8765-8785 are unavailable.","GPT Image Tool",MB_ICONERROR);return 1;}char url[256];snprintf(url,sizeof(url),"http://127.0.0.1:%d/index.html",port);printf("GPT Image Tool PC Developer v1.0 started.\nParallel generation/edit proxy: enabled.\nURL: %s\nKeep this window open. Press Ctrl+C to stop.\n",url);ShellExecuteA(NULL,"open",url,NULL,root,SW_SHOWNORMAL);for(;;){SOCKET c=accept(server,NULL,NULL);if(c==INVALID_SOCKET)break;CLIENT_JOB*j=(CLIENT_JOB*)calloc(1,sizeof(CLIENT_JOB));if(!j){closesocket(c);continue;}j->client=c;strncpy(j->root,root,sizeof(j->root)-1);HANDLE th=CreateThread(NULL,0,client_worker,j,0,NULL);if(th)CloseHandle(th);else{closesocket(c);free(j);}}DeleteCriticalSection(&history_lock);return 0;}
